*{box-sizing:border-box} :root{--ink:#203b38;--muted:#7f918a;--cream:#fffdf5;--green:#34785f;--gold:#eab64d}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#d9e8d0;font-family:'DM Sans',sans-serif;color:var(--ink);touch-action:none}#game-shell{position:relative;width:100%;height:100%;overflow:hidden;background:#a9d69f}canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(18,47,45,.18),transparent 20%,transparent 72%,rgba(18,47,45,.12))}.topbar{position:absolute;z-index:2;top:20px;left:25px;right:25px;height:68px;display:flex;align-items:center;justify-content:space-between;padding:0 15px 0 17px;border-radius:20px;background:rgba(255,253,245,.94);box-shadow:0 8px 26px #29534b25;backdrop-filter:blur(12px)}.brand{display:flex;align-items:center;gap:11px;min-width:215px}.brand-mark{width:39px;height:39px;display:grid;place-items:center;border-radius:13px;background:#e6f0d7;color:#4f8966;font-size:25px}.brand-name{font-family:Fraunces,serif;font-weight:800;font-size:16px;letter-spacing:1.55px;line-height:1}.brand-sub{font-size:8px;letter-spacing:1.65px;color:#8da098;margin-top:5px;font-weight:700}.top-center{display:flex;align-items:center;gap:11px;color:#567268}.top-center strong{display:block;font-size:12px}.top-center small{display:block;color:#9aa8a0;font-size:10px;margin-top:3px}.weather-icon{width:36px;height:36px;background:#fff2cd;color:#e3a73b;border-radius:12px;display:grid;place-items:center;font-size:20px}.divider{height:28px;width:1px;background:#e4e9df;margin:0 4px}.weather-note{font-size:11px;color:#869a8f}.wallet{display:flex;align-items:baseline;gap:6px;padding:10px 13px;border-radius:14px;background:#f4f4e9;color:#527358}.wallet .coin{color:#dfac41;font-size:17px}.wallet strong{font-family:Fraunces,serif;font-size:19px;color:#3d654e}.wallet small{font-size:9px;color:#92a094}.location-card,.quest-card{position:absolute;z-index:2;left:27px;top:108px;padding:12px 15px;display:flex;align-items:center;gap:11px;border-radius:15px;background:#fffdf2e8;box-shadow:0 5px 16px #2c524422;backdrop-filter:blur(8px)}.location-pin{width:31px;height:31px;display:grid;place-items:center;border-radius:10px;background:#dcede0;color:#438365;font-size:21px}.location-card small,.quest-card small{display:block;font-size:8px;letter-spacing:1.2px;font-weight:800;color:#92a39a}.location-card strong,.quest-card strong{display:block;font-family:Fraunces,serif;font-size:14px;margin-top:3px;color:#355448}.location-spark{color:#dbb54f;margin-left:12px}.quest-card{top:160px;width:228px;gap:9px;padding:10px 12px}.quest-icon{width:29px;height:29px;display:grid;place-items:center;background:#f5e9c9;color:#b38a39;border-radius:9px;font-size:17px}.quest-card>div:nth-child(2){flex:1}.quest-card strong{font:700 10px 'DM Sans';margin-top:4px}.quest-progress{height:4px;border-radius:5px;background:#e9e9dc;margin-top:7px;overflow:hidden}.quest-progress i{display:block;width:0;height:100%;background:#79a974;border-radius:5px;transition:width .3s}.quest-card>span:last-child{font-size:9px;color:#84948a;font-weight:700}.icon-button{border:0;position:absolute;z-index:2;right:28px;top:109px;width:63px;height:59px;background:#fffdf2e8;border-radius:15px;color:#527768;box-shadow:0 5px 15px #2c524422;cursor:pointer}.icon-button span{font-size:21px;display:block}.icon-button small{font-size:7px;letter-spacing:1px;font-weight:800}.inventory-strip{position:absolute;z-index:2;bottom:23px;left:50%;transform:translateX(-50%);height:68px;min-width:440px;padding:8px 12px;display:flex;align-items:center;gap:12px;background:#fffdf4f2;border:1px solid #fff;border-radius:19px;box-shadow:0 8px 26px #224b4330;backdrop-filter:blur(14px)}.rod-icon{height:46px;width:46px;border-radius:14px;background:#e7efda;display:grid;place-items:center;color:#457861;font-size:26px}.rod-info{min-width:119px}.rod-info small,.bait-button small{display:block;font-size:8px;letter-spacing:1.2px;color:#96a49a;font-weight:800}.rod-info strong{display:block;margin-top:4px;font-size:11px;color:#45644e}.rod-info em{font-size:9px;font-style:normal;color:#a6a99a}.strip-divider{height:38px;width:1px;background:#e7e8dc}.bait-button,.bag-button{border:0;background:#f4f4e8;border-radius:12px;height:46px;display:flex;align-items:center;gap:8px;padding:0 10px;color:#3f664f;cursor:pointer}.bait-button>span:first-child{font-size:19px}.bait-button small{letter-spacing:.5px;white-space:nowrap}.bait-button small b{color:#5d7e63}.bait-button strong{display:block;font-size:10px;text-align:left;margin-top:3px}.bait-button i{font-style:normal;font-size:15px;color:#9aa899;margin-left:2px}.bag-button{flex-direction:column;justify-content:center;gap:1px;width:54px}.bag-button span{font-size:16px}.bag-button small{font-size:7px;letter-spacing:.5px;color:#8d9d90}.bag-button b{color:#527d60}.control-hint{position:absolute;z-index:2;bottom:103px;left:50%;transform:translateX(-50%);padding:7px 12px;border-radius:9px;background:#2049409e;color:#eff4df;font-size:9px;white-space:nowrap;letter-spacing:.15px}.control-hint span{padding:3px 5px;border:1px solid #ffffff58;border-radius:4px;font-size:8px;font-weight:800}.control-hint b{padding:0 5px;color:#c5d6b3}.toast{position:absolute;z-index:20;left:50%;top:105px;transform:translate(-50%,-10px);opacity:0;pointer-events:none;padding:11px 16px;background:#254e43;color:#fff9e9;border-radius:13px;font-size:12px;font-weight:700;box-shadow:0 8px 22px #193c343d;transition:.25s}.toast.show{opacity:1;transform:translate(-50%,0)}.fish-notice{display:none;position:absolute;z-index:4;top:35%;left:50%;transform:translate(-50%,-50%);align-items:center;gap:12px;padding:13px 17px;background:#fffdf4;border-radius:16px;box-shadow:0 8px 25px #234d4338;animation:bob .8s ease-in-out infinite alternate}.fish-notice.visible{display:flex}.fish-notice>span{font-size:29px;color:#4b9d91}.fish-notice small{display:block;color:#79a08c;font-size:8px;letter-spacing:1.1px;font-weight:800}.fish-notice strong{display:block;font-family:Fraunces,serif;font-size:17px;margin-top:3px}.fish-notice>b{font-size:8px;border:1px solid #dfe5d6;padding:6px;border-radius:6px;color:#6d8274}.mobile-actions,.joystick{display:none}.panel-shade{display:none;position:absolute;z-index:5;inset:0;background:#173c3566;backdrop-filter:blur(2px)}.panel-shade.open{display:block}.game-panel{display:none;position:absolute;z-index:6;left:50%;top:50%;transform:translate(-50%,-50%);width:min(510px,calc(100% - 32px));max-height:calc(100% - 95px);overflow:auto;background:#fffdf4;border-radius:23px;box-shadow:0 20px 70px #14372f50;padding:23px;color:#345448}.game-panel.open{display:block;animation:panelIn .18s ease-out}.panel-title-row{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:17px}.panel-kicker{font-size:8px;letter-spacing:1.7px;font-weight:800;color:#93a296}.panel-title{font:800 26px Fraunces,serif;color:#315345;margin-top:4px}.close-panel{border:0;width:34px;height:34px;border-radius:11px;background:#f0f1e5;color:#64806c;font-size:19px;cursor:pointer}.panel-intro{font-size:12px;color:#7e9084;line-height:1.5;margin:-5px 0 15px}.panel-grid{display:grid;gap:9px}.item-row{display:flex;align-items:center;gap:12px;padding:11px;border:1px solid #eceee1;background:#fffef9;border-radius:15px}.item-emoji{width:43px;height:43px;border-radius:13px;background:#eff2e4;display:grid;place-items:center;font-size:23px;flex-shrink:0}.item-copy{flex:1;min-width:0}.item-copy strong{display:block;font-size:12px;color:#415f4d}.item-copy small{display:block;font-size:10px;color:#91a096;margin-top:4px}.item-price{font-size:10px;color:#b28b3c;font-weight:800;white-space:nowrap}.pill{display:inline-block;font-size:8px;padding:3px 6px;border-radius:5px;background:#edf2df;color:#63825b;margin-left:4px;font-weight:800}.main-button,.soft-button{border:0;border-radius:11px;padding:10px 13px;background:#4f8768;color:#fffdf2;font:700 10px 'DM Sans';cursor:pointer;white-space:nowrap}.main-button:hover{background:#3d7459}.main-button:disabled{opacity:.45;cursor:default}.soft-button{background:#eef1e5;color:#63806b}.row-button{min-width:70px}.panel-footer{display:flex;justify-content:space-between;align-items:center;margin-top:15px;padding-top:13px;border-top:1px solid #eceee4;font-size:10px;color:#89968a}.stat-line{display:flex;gap:7px;flex-wrap:wrap;margin-top:6px}.stat-chip{border-radius:6px;padding:4px 6px;background:#f0f3e7;font-size:9px;color:#698267}.minigame{display:none;position:absolute;z-index:4;left:50%;top:50%;transform:translate(-50%,-50%);width:min(400px,calc(100% - 34px))}.minigame.active{display:block;animation:panelIn .2s ease-out}.minigame-card{padding:17px;background:#fffdf4;border-radius:19px;box-shadow:0 12px 40px #1e453d50}.minigame-head{display:flex;align-items:center;gap:10px}.minigame-head>span{width:39px;height:39px;border-radius:12px;display:grid;place-items:center;background:#fff1cc;color:#d09f3e;font-size:20px}.minigame-head div{flex:1}.minigame-head small{display:block;color:#c48a47;letter-spacing:1px;font-size:8px;font-weight:800}.minigame-head strong{font:700 16px Fraunces,serif;display:block;margin-top:3px}.minigame-head>b{font-size:12px;color:#8a998e;background:#f1f2e8;border-radius:8px;padding:7px 9px}.reel-track{position:relative;height:12px;margin:17px 3px 7px;background:#e9ecdf;border-radius:9px;overflow:visible}.reel-track i{height:100%;width:0;display:block;border-radius:9px;background:linear-gradient(90deg,#8fc47b,#e5b752);transition:width .2s}.reel-track span{position:absolute;top:-8px;left:78%;color:#dfaf43;font-size:23px;animation:twinkle .6s infinite alternate}.minigame-help{text-align:center;color:#9aa398;font-size:10px;margin:10px 0 12px}.minigame-help b{color:#537d5d}.minigame-card>button{width:100%;border:0;border-radius:12px;padding:13px;background:#4d8667;color:#fffbed;font-weight:800;font-size:11px;letter-spacing:1px;cursor:pointer}.minigame-card>button span{margin-left:8px}.rarity-common{color:#6e9a72!important}.rarity-rare{color:#5793ad!important}.rarity-epic{color:#aa79bd!important}.rarity-legendary{color:#d39d37!important}@keyframes bob{to{transform:translate(-50%,-57%)}}@keyframes panelIn{from{opacity:0;transform:translate(-50%,-47%)}to{opacity:1;transform:translate(-50%,-50%)}}@keyframes twinkle{to{transform:scale(1.35);opacity:.55}}
@media(max-width:700px){.topbar{top:9px;left:9px;right:9px;height:54px;padding:0 9px;border-radius:16px}.brand{min-width:0;gap:7px}.brand-mark{height:34px;width:34px;font-size:21px;border-radius:11px}.brand-name{font-size:12px;letter-spacing:1px}.brand-sub{font-size:6px;letter-spacing:1px;margin-top:4px}.top-center{gap:7px}.top-center .weather-note,.top-center .divider{display:none}.top-center strong{font-size:10px}.top-center small{font-size:8px}.weather-icon{width:30px;height:30px;font-size:17px;border-radius:10px}.wallet{padding:8px 9px;gap:4px}.wallet strong{font-size:15px}.wallet small{font-size:8px}.location-card{left:10px;top:72px;padding:8px 10px;gap:7px;border-radius:12px}.location-pin{height:27px;width:27px;font-size:17px}.location-card small{font-size:6px}.location-card strong{font-size:11px}.location-spark{margin-left:1px;font-size:10px}.quest-card{left:10px;top:117px;width:187px;padding:8px 9px;gap:6px}.quest-icon{width:23px;height:23px;font-size:14px}.quest-card small{font-size:6px}.quest-card strong{font-size:8px}.quest-progress{margin-top:5px}.quest-card>span:last-child{font-size:8px}.icon-button{right:10px;top:72px;width:44px;height:43px;border-radius:12px}.icon-button span{font-size:17px}.icon-button small{font-size:6px}.inventory-strip{bottom:10px;left:50%;min-width:0;width:calc(100% - 20px);height:58px;padding:6px 7px;gap:7px;border-radius:16px}.rod-icon{width:37px;height:39px;border-radius:11px;font-size:22px}.rod-info{min-width:74px}.rod-info small,.bait-button small{font-size:6px;letter-spacing:.7px}.rod-info strong{font-size:9px}.rod-info em{font-size:7px}.strip-divider{height:30px}.bait-button{height:39px;padding:0 6px;gap:5px;flex:1;justify-content:center}.bait-button>span:first-child{font-size:15px}.bait-button strong{font-size:8px}.bait-button i{font-size:12px}.bag-button{height:39px;width:43px;padding:0 4px}.bag-button span{font-size:14px}.bag-button small{font-size:6px}.control-hint{display:none}.joystick{display:block;position:absolute;z-index:3;left:14px;bottom:84px;width:100px;height:100px}.joy-ring{position:absolute;inset:0;border-radius:50%;background:#fffaf0a6;border:2px solid #ffffffe0;box-shadow:0 4px 16px #234d4328}.joy-knob{position:absolute;left:50%;top:50%;width:41px;height:41px;margin:-20.5px;border-radius:50%;background:#739b78;border:3px solid #fff9e8;box-shadow:0 3px 8px #31594450;transform:translate(0,0)}.mobile-actions{display:flex;position:absolute;z-index:3;right:14px;bottom:86px;align-items:center;gap:8px}.action-button,.small-action{border:0;cursor:pointer;color:#fffbed;background:#477b61;box-shadow:0 5px 14px #214b3d60}.action-button{width:68px;height:68px;border-radius:50%;display:flex;flex-direction:column;justify-content:center;align-items:center;border:3px solid #f8f6df}.action-button span{font-size:24px;line-height:24px}.action-button b{font-size:8px;letter-spacing:1px;margin-top:2px}.small-action{width:43px;height:43px;border-radius:50%;font-size:18px;border:2px solid #f8f6df}.fish-notice{top:42%;padding:10px 12px;gap:9px}.fish-notice strong{font-size:14px}.fish-notice small{font-size:7px}.fish-notice>b{font-size:7px}.game-panel{padding:17px;border-radius:19px;max-height:calc(100% - 76px)}.panel-title{font-size:23px}.item-row{padding:8px;gap:8px}.item-emoji{width:37px;height:37px;font-size:20px}.item-copy strong{font-size:10px}.item-copy small{font-size:8px}.main-button,.soft-button{padding:9px 10px;font-size:9px}.minigame{top:48%}.minigame-card{padding:14px}.toast{top:69px;font-size:10px;padding:9px 12px;max-width:90%;white-space:nowrap}}
@media(max-height:500px){.topbar{height:48px;top:7px}.location-card{top:64px}.quest-card{top:108px}.inventory-strip{bottom:7px;height:53px}.control-hint{bottom:72px}.joystick,.mobile-actions{bottom:68px}.game-panel{max-height:calc(100% - 55px);padding:14px}.item-row{padding:6px}}

(() => {
  const canvas = document.getElementById('world'), ctx = canvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const state = {
    player:{x:510,y:625,dir:0}, coins:128, rod:{name:'Willow Rod',level:1,power:1,luck:0}, bait:'Worm', baitCount:8,
    bag:[], fishCaught:0, cacheFound:0, moving:{x:0,y:0}, keys:{}, cast:null, reel:null, panel:null, outfit:null,
    gear:{hat:null,coat:null,boots:null}, caches:[{x:270,y:570,found:false},{x:1120,y:340,found:false},{x:1740,y:980,found:false},{x:1330,y:1310,found:false}],
    start:performance.now(), last:performance.now(), toastTimer:0, joystick:null, moveFast:false
  };
  const W=2200,H=1600, zones=[
    {name:'Willowmere Pond',x:0,y:0,w:850,h:850}, {name:'Whispering Grove',x:850,y:0,w:700,h:700},
    {name:'Mosslight Marsh',x:1500,y:0,w:700,h:800}, {name:'Sunmeadow Fields',x:0,y:850,w:850,h:750},
    {name:'Fernfall Highlands',x:850,y:700,w:700,h:900}, {name:'Saltwind Coast',x:1550,y:800,w:650,h:800}
  ];
  const ponds=[{x:510,y:420,rx:440,ry:285,kind:0},{x:1170,y:310,rx:250,ry:185,kind:1},{x:1700,y:370,rx:285,ry:230,kind:2},{x:1190,y:1050,rx:300,ry:180,kind:3},{x:1920,y:1200,rx:370,ry:210,kind:4}];
  const rand=(n)=>{let x=Math.sin(n*127.1+31.7)*43758.5453;return x-Math.floor(x)};
  let dpr=1,cw=innerWidth,ch=innerHeight,cam={x:0,y:0};
  function resize(){dpr=Math.min(devicePixelRatio||1,2);cw=innerWidth;ch=innerHeight;canvas.width=cw*dpr;canvas.height=ch*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}
  addEventListener('resize',resize);resize();
  function rr(c,x,y,w,h,r){c.beginPath();c.roundRect(x,y,w,h,r)}
  function drawWorld(t){
    ctx.clearRect(0,0,cw,ch); const s=Math.max(.65,Math.min(1.05,cw/1050));
    const viewW=cw/s,viewH=ch/s; cam.x=Math.max(0,Math.min(W-viewW,state.player.x-viewW*.5));cam.y=Math.max(0,Math.min(H-viewH,state.player.y-viewH*.52));
    ctx.save();ctx.scale(s,s);ctx.translate(-cam.x,-cam.y);
    // soft painterly ground
    ctx.fillStyle='#a9d79c';ctx.fillRect(0,0,W,H);
    for(let i=0;i<180;i++){let x=rand(i+8)*W,y=rand(i+91)*H;ctx.fillStyle=i%2?'#b4dfa0':'#9ed18e';ctx.globalAlpha=.16;ctx.beginPath();ctx.ellipse(x,y,35+rand(i)*42,20+rand(i+4)*28,rand(i+9),0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
    // region tint fields
    ctx.fillStyle='#c2df9e';ctx.globalAlpha=.23;ctx.fillRect(0,850,850,750);ctx.fillStyle='#96c887';ctx.fillRect(850,700,700,900);ctx.fillStyle='#a4d49b';ctx.fillRect(1500,0,700,800);ctx.fillStyle='#e2d991';ctx.fillRect(1550,800,650,800);ctx.globalAlpha=1;
    // paths winding through the world
    ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#d9c99a';ctx.lineWidth=44;ctx.beginPath();ctx.moveTo(420,720);ctx.bezierCurveTo(750,660,700,540,970,590);ctx.bezierCurveTo(1120,620,1040,830,1230,850);ctx.bezierCurveTo(1510,900,1440,1120,1760,1090);ctx.stroke();
    ctx.strokeStyle='#eee0b1';ctx.lineWidth=31;ctx.beginPath();ctx.moveTo(420,720);ctx.bezierCurveTo(750,660,700,540,970,590);ctx.bezierCurveTo(1120,620,1040,830,1230,850);ctx.bezierCurveTo(1510,900,1440,1120,1760,1090);ctx.stroke();
    // water bodies with rippling edges
    for(let p=0;p<ponds.length;p++){const q=ponds[p];ctx.save();ctx.translate(q.x,q.y);ctx.fillStyle='#75bdbc';ctx.beginPath();ctx.ellipse(0,0,q.rx+9,q.ry+8,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=['#7cc7c0','#83c9bf','#79bbb0','#78c4bd','#6fb4b7'][q.kind];ctx.beginPath();ctx.ellipse(0,0,q.rx,q.ry,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=.35;ctx.strokeStyle='#e3f3d9';ctx.lineWidth=3;for(let k=0;k<8;k++){let x=Math.sin(t*.0004+k*3)*q.rx*.66,y=Math.cos(t*.0003+k*4)*q.ry*.58;ctx.beginPath();ctx.ellipse(x,y,18+k%3*9,4,0,0,Math.PI*2);ctx.stroke()}ctx.globalAlpha=1;ctx.restore();}
    // coast/sand strips
    ctx.fillStyle='#e7d79d';ctx.beginPath();ctx.moveTo(1580,840);ctx.quadraticCurveTo(1670,900,1770,870);ctx.quadraticCurveTo(1910,840,2040,920);ctx.lineTo(2200,880);ctx.lineTo(2200,970);ctx.quadraticCurveTo(2030,1010,1900,960);ctx.quadraticCurveTo(1730,900,1570,960);ctx.fill();
    // flowers & grass tufts
    for(let i=0;i<460;i++){let x=rand(i+401)*W,y=rand(i+908)*H;if(ponds.some(p=>((x-p.x)/p.rx)**2+((y-p.y)/p.ry)**2<1.08))continue;let sx=x-cam.x,sy=y-cam.y;if(sx<-50||sy<-50||sx>viewW+50||sy>viewH+50)continue;let c=['#fff2c3','#f4ac9f','#fff8e0','#d3c3ed'][Math.floor(rand(i+80)*4)];ctx.globalAlpha=.5;ctx.fillStyle=c;ctx.beginPath();ctx.arc(x,y,1.5+rand(i+8)*1.5,0,7);ctx.fill();ctx.globalAlpha=1;}
    // trees around village, forest and banks
    for(let i=0;i<135;i++){let x=rand(i+44)*W,y=rand(i+322)*H;let grove=(x>850&&x<1550&&y<750);let marsh=(x>1500&&y<800);if((Math.abs(x-510)<440&&Math.abs(y-420)<285)||ponds.some(p=>((x-p.x)/p.rx)**2+((y-p.y)/p.ry)**2<1.18))continue;if(!grove&&!marsh&&rand(i+11)>.24)continue;tree(x,y,grove?'#588b62':marsh?'#548677':'#568854',i);}
    for(let i=0;i<55;i++){let x=rand(i+766)*W,y=rand(i+2122)*H;if(ponds.some(p=>((x-p.x)/p.rx)**2+((y-p.y)/p.ry)**2<1.05))continue;stone(x,y,i)}
    // village houses / market
    house(735,690,'#d58d67','#6d8358','MARNIE\'S MARKET');house(350,820,'#edc88c','#75946b','');house(810,850,'#d8a277','#6e8761','');
    // docks and fishing signs
    dock(470,575,90);dock(1050,390,72);dock(1660,500,83);dock(1050,1130,85);dock(1915,1330,90);
    sign(680,750,'SELL');sign(510,600,'FISH');
    // cache boxes
    state.caches.forEach((c,i)=>{if(!c.found)cacheDraw(c.x,c.y,t,i)});
    // player
    drawPlayer(state.player.x,state.player.y,t);
    // cast line and bobber
