function cacheDraw(x,y,t,i){ctx.fillStyle='#55704e';ctx.beginPath();ctx.ellipse(x,y+10,20,7,0,0,7);ctx.fill();ctx.fillStyle='#9d6943';rr(ctx,x-13,y-8,26,19,5);ctx.fill();ctx.fillStyle='#d2a35a';ctx.fillRect(x-13,y-4,26,4);ctx.fillRect(x-2,y-7,4,17);ctx.fillStyle='#ffe294';ctx.globalAlpha=.55+Math.sin(t*.004+i)*.3;ctx.beginPath();ctx.arc(x,y-17,3,0,7);ctx.fill();ctx.globalAlpha=1;}
function drawPlayer(x,y,t){ctx.fillStyle='#506d54';ctx.beginPath();ctx.ellipse(x,y+13,17,7,0,0,7);ctx.fill();ctx.fillStyle='#d3a275';ctx.fillRect(x-9,y-7,7,18);ctx.fillRect(x+3,y-7,7,18);ctx.fillStyle=state.outfit?.color||'#e4a77e';rr(ctx,x-12,y-19,24,24,8);ctx.fill();ctx.fillStyle='#f0d7b5';ctx.beginPath();ctx.arc(x,y-27,10,0,7);ctx.fill();ctx.fillStyle='#594d3d';ctx.beginPath();ctx.arc(x,y-31,10,Math.PI,Math.PI*2);ctx.fill();ctx.fillRect(x-10,y-31,20,5);if(state.gear.hat){ctx.fillStyle=state.gear.hat.color;ctx.beginPath();ctx.ellipse(x,y-35,15,4,0,0,7);ctx.fill();ctx.fillRect(x-8,y-42,16,8)}ctx.fillStyle='#384c42';let eyeY=y-28;ctx.beginPath();ctx.arc(x+(state.player.dir===1?4:-4),eyeY,1.3,0,7);ctx.fill();ctx.strokeStyle='#79563c';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x+12,y-15);ctx.lineTo(x+18,y-38);ctx.stroke();ctx.fillStyle='#f7e4ba';ctx.beginPath();ctx.arc(x+18,y-38,2,0,7);ctx.fill();}
function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
function currentZone(){return zones.find(z=>state.player.x>=z.x&&state.player.x<z.x+z.w&&state.player.y>=z.y&&state.player.y<z.y+z.h)||zones[0]}
function updateHud(){ $('coins').textContent=state.coins;$('rod-name').innerHTML=`${state.rod.name} <em>· Lv. ${state.rod.level}</em>`;$('bait-name').textContent=state.bait;$('bait-count').textContent=`${state.baitCount} left`;$('bag-count').textContent=state.bag.length;$('biome-label').textContent=currentZone().name;$('quest-count').textContent=`${Math.min(3,state.fishCaught)}/3`;$('quest-fill').style.width=`${Math.min(100,state.fishCaught/3*100)}%`;}
function notify(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function fishable(){return ponds.some(p=>{let dx=(state.player.x-p.x)/p.rx,dy=(state.player.y-p.y)/p.ry;return dx*dx+dy*dy<1.38})}
function nearCache(){return state.caches.find(c=>!c.found&&dist(c,state.player)<70)}
function nearMarket(){return dist({x:770,y:735},state.player)<115}
function interact(){if(state.panel){closePanel();return}let c=nearCache();if(c){openCache(c);return}if(nearMarket()){openShop();return}if(state.reel){reelTap();return}if(state.cast?.phase==='bite'){startReel();return}if(state.cast){notify('Your bobber is out there — wait for a nibble!');return}if(!fishable()){notify('Find a pond, marsh or shoreline to cast your line.');return}startCast()}
function startCast(){if(state.baitCount<=0){notify('Out of bait! Tap the bait pouch to restock.');return}state.baitCount--;let near=ponds.filter(p=>Math.hypot((state.player.x-p.x)*.75,state.player.y-p.y)<p.rx+100).sort((a,b)=>Math.hypot(state.player.x-a.x,state.player.y-a.y)-Math.hypot(state.player.x-b.x,state.player.y-b.y))[0]||ponds[0];let angle=Math.atan2(near.y-state.player.y,near.x-state.player.x);let len=125+Math.random()*40;state.cast={phase:'waiting',point:{x:state.player.x+Math.cos(angle)*len,y:state.player.y+Math.sin(angle)*len},until:performance.now()+3600+Math.random()*3500};updateHud();notify('Nice cast! Keep an eye on the bobber.');}
const fishTypes=[
  {name:'Pond Minnow',icon:'🐟',value:12,rarity:'Common',biomes:['Willowmere Pond','Sunmeadow Fields']},
  {name:'Golden Perch',icon:'🐠',value:28,rarity:'Uncommon',biomes:['Willowmere Pond','Whispering Grove']},
  {name:'Bluegill',icon:'🐟',value:18,rarity:'Common',biomes:['Willowmere Pond','Whispering Grove']},
  {name:'Mossy Carp',icon:'🐡',value:34,rarity:'Uncommon',biomes:['Mosslight Marsh','Whispering Grove']},
  {name:'Moonfin',icon:'🐟',value:75,rarity:'Rare',biomes:['Mosslight Marsh','Fernfall Highlands']},
  {name:'Silver Trout',icon:'🐟',value:44,rarity:'Uncommon',biomes:['Fernfall Highlands','Whispering Grove']},
  {name:'Sunscale Koi',icon:'🐠',value:120,rarity:'Epic',biomes:['Sunmeadow Fields','Willowmere Pond']},
  {name:'Starry Flounder',icon:'🐟',value:64,rarity:'Rare',biomes:['Saltwind Coast']},
  {name:'Tideglass Eel',icon:'🐍',value:145,rarity:'Epic',biomes:['Saltwind Coast','Mosslight Marsh']},
  {name:'Elder Sturgeon',icon:'🐋',value:330,rarity:'Legendary',biomes:['Willowmere Pond','Fernfall Highlands']}
];
function startReel(){state.cast.phase='reel';state.reel={progress:0,time:10,quality:Math.random()};$('fish-notice').classList.remove('visible');$('minigame').classList.add('active');}
function reelTap(){if(!state.reel)return;let r=state.reel;r.progress+=13+Math.random()*6+(state.rod.power-1)*2;if(r.progress>=100){finishCatch();return}if(r.progress>52&&r.progress<68)r.progress+=7;$('reel-fill').style.width=Math.min(100,r.progress)+'%';}
function finishCatch(){let zone=currentZone().name, pool=fishTypes.filter(f=>f.biomes.includes(zone));if(!pool.length)pool=fishTypes.slice(0,4);let bonus=(state.bait==='Glow Grub'?.12:state.bait==='Honeyfly'?.08:0)+state.rod.luck*.025+(state.gear.coat?.luck||0)*.02;let roll=Math.random()-bonus;let fish=pool[Math.floor(Math.random()*pool.length)];if(roll<.018)fish=fishTypes.find(f=>f.rarity==='Legendary')||fish;if(roll<.08&&fish.rarity==='Common')fish=pool.find(f=>f.rarity==='Rare')||fish;let variant=Math.random()<(fish.rarity==='Legendary'?.34:.11+bonus)?['Golden','Prismatic','Twilight'][Math.floor(Math.random()*3)]:null;let catchItem={...fish,value:Math.round(fish.value*(variant?3:1)),variant,quality:Math.min(100,65+Math.round(state.reel.progress/4))};state.bag.push(catchItem);state.fishCaught++;state.cast=null;state.reel=null;$('minigame').classList.remove('active');updateHud();notify(`${variant?variant+' ':''}${fish.name} caught!`);}
function cancelCast(){state.cast=null;state.reel=null;$('fish-notice').classList.remove('visible');$('minigame').classList.remove('active');}
function openPanel(title,kicker,content){state.panel=true;$('panel-shade').classList.add('open');const p=$('game-panel');p.innerHTML=`<div class="panel-title-row"><div><div class="panel-kicker">${kicker}</div><div class="panel-title">${title}</div></div><button class="close-panel" id="panel-close">×</button></div>${content}`;p.classList.add('open');$('panel-close').onclick=closePanel;}
function closePanel(){state.panel=false;$('panel-shade').classList.remove('open');$('game-panel').classList.remove('open');}
$('panel-shade').onclick=closePanel;
function openBag(){let fishRows=state.bag.map((f,i)=>`<div class="item-row"><div class="item-emoji">${f.icon}</div><div class="item-copy"><strong class="rarity-${f.rarity.toLowerCase()}">${f.variant?f.variant+' ':''}${f.name}<span class="pill">${f.rarity}</span></strong><small>Quality ${f.quality}% · Sell value ${f.value} shells</small></div><button class="soft-button row-button" data-release="${i}">Release</button></div>`).join('');openPanel('Your Satchel','FISHING JOURNAL',`<p class="panel-intro">A little collection of things you've found on your travels.</p><div class="panel-grid">${fishRows||'<div class="item-row"><div class="item-emoji">🫧</div><div class="item-copy"><strong>Your satchel is empty</strong><small>Cast a line near the water to catch your first fish.</small></div></div>'}</div><div class="panel-footer"><span>${state.bag.length} fish in your satchel</span><button class="main-button" id="sell-all" ${state.bag.length?'':'disabled'}>Sell all · ${state.bag.reduce((n,f)=>n+f.value,0)} ✦</button></div>`);document.querySelectorAll('[data-release]').forEach(b=>b.onclick=()=>{state.bag.splice(+b.dataset.release,1);updateHud();openBag()});$('sell-all').onclick=()=>sellAll();}
function sellAll(){if(!state.bag.length)return;let total=state.bag.reduce((n,f)=>n+f.value,0);state.coins+=total;let count=state.bag.length;state.bag=[];updateHud();closePanel();notify(`Sold ${count} fish for ${total} shells!`)}

