  function update(dt,now){let speed=(state.moveFast?240:162)*(1+(state.gear.boots?.speed||0)*.05);let mx=state.moving.x+(state.keys.KeyD||state.keys.ArrowRight?1:0)-(state.keys.KeyA||state.keys.ArrowLeft?1:0);let my=state.moving.y+(state.keys.KeyS||state.keys.ArrowDown?1:0)-(state.keys.KeyW||state.keys.ArrowUp?1:0);let m=Math.hypot(mx,my);if(m>1){mx/=m;my/=m}if(m>.08&&!state.panel&&!state.reel){state.player.x=Math.max(22,Math.min(W-22,state.player.x+mx*speed*dt));state.player.y=Math.max(40,Math.min(H-22,state.player.y+my*speed*dt));if(Math.abs(mx)>.1)state.player.dir=mx>0?1:0;if(state.cast&&state.cast.phase==='waiting')cancelCast()}
    if(state.cast?.phase==='waiting'&&now>state.cast.until){state.cast.phase='bite';$('fish-notice').classList.add('visible');setTimeout(()=>{if(state.cast?.phase==='bite'){cancelCast();notify('The fish got away — try another cast!')}},4800)}
    if(state.reel){state.reel.time-=dt;if(Math.random()<dt*.75)state.reel.progress=Math.max(0,state.reel.progress-4);$('reel-fill').style.width=Math.min(100,state.reel.progress)+'%';$('reel-time').textContent=Math.ceil(state.reel.time);if(state.reel.time<=0){cancelCast();notify('The fish slipped away! Try again.')}}
    if(state.fishCaught>=3&&state.fishCaught<4){state.fishCaught=4;state.coins+=80;notify('Quest complete! Marnie sent you 80 shells!')}updateHud();}
  function loop(now){let dt=Math.min(.05,(now-state.last)/1000);state.last=now;update(dt,now);drawWorld(now);requestAnimationFrame(loop)}
  addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Space'||e.code==='KeyE'){interact();return}if(e.code==='KeyB'){openBag();return}if(e.code==='KeyJ'){openJournal();return}state.keys[e.code]=true});addEventListener('keyup',e=>state.keys[e.code]=false);
  $('action-button').onclick=interact;$('bag-button').onclick=openBag;$('bait-button').onclick=openBaits;$('journal-button').onclick=openJournal;$('move-button').onpointerdown=()=>state.moveFast=true;$('move-button').onpointerup=$('move-button').onpointerleave=()=>state.moveFast=false;
  // Drag joystick: keep the knob and movement vector inside the base circle.
  const joy=$('joystick'),knob=$('joy-knob');joy.addEventListener('pointerdown',e=>{e.preventDefault();joy.setPointerCapture(e.pointerId);state.joystick=e.pointerId;moveJoy(e)});joy.addEventListener('pointermove',e=>{if(state.joystick===e.pointerId)moveJoy(e)});function moveJoy(e){let r=joy.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),limit=31,d=Math.hypot(dx,dy);if(d>limit){dx*=limit/d;dy*=limit/d}knob.style.transform=`translate(${dx}px,${dy}px)`;state.moving.x=dx/limit;state.moving.y=dy/limit}function endJoy(e){if(state.joystick!==e.pointerId)return;state.joystick=null;state.moving={x:0,y:0};knob.style.transform='translate(0,0)'}joy.addEventListener('pointerup',endJoy);joy.addEventListener('pointercancel',endJoy);
  $('reel-button').onclick=reelTap;$('bag-button').title='Open your satchel (B)';$('journal-button').title='Open your field notes (J)';$('control-hint').innerHTML='<span>WASD</span> move <b>·</b> <span>SPACE</span> fish / interact <b>·</b> <span>B</span> bag <b>·</b> <span>J</span> journal';
  updateHud();requestAnimationFrame(loop);
})();

